USE `laboratorio_la_2026`;
SELECT CASE WHEN (SELECT COUNT(*) FROM roles)=3 AND (SELECT COUNT(*) FROM usuarios)=3 AND (SELECT COUNT(*) FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol WHERE u.id_usuario=1 AND u.nombre_usuario='admin' AND u.activo=1 AND r.id_rol=1 AND r.nombre='ADMIN')=1 AND (SELECT COUNT(*) FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol WHERE u.id_usuario=2 AND u.nombre_usuario='recepcion' AND u.activo=1 AND r.id_rol=2 AND r.nombre='RECEPCIONISTA')=1 AND (SELECT COUNT(*) FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol WHERE u.id_usuario=3 AND u.nombre_usuario='tecnico' AND u.activo=1 AND r.id_rol=3 AND r.nombre='TECNICO')=1 AND (SELECT COUNT(*) FROM `centros_derivantes`)=0 AND (SELECT COUNT(*) FROM `insumos`)=0 AND (SELECT COUNT(*) FROM `obras_sociales`)=0 AND (SELECT COUNT(*) FROM `pacientes`)=0 AND (SELECT COUNT(*) FROM `ordenes`)=0 AND (SELECT COUNT(*) FROM `analisis`)=0 AND (SELECT COUNT(*) FROM `configuracion_tarifas`)=0 AND (SELECT COUNT(*) FROM `cotizaciones`)=0 AND (SELECT COUNT(*) FROM `movimientos_stock`)=0 AND (SELECT COUNT(*) FROM `muestras`)=0 AND (SELECT COUNT(*) FROM `coberturas_analisis`)=0 AND (SELECT COUNT(*) FROM `derivaciones`)=0 AND (SELECT COUNT(*) FROM `orden_analisis`)=0 AND (SELECT COUNT(*) FROM `cotizacion_detalle`)=0 AND (SELECT COUNT(*) FROM `muestra_analisis`)=0 THEN 'LISTO_PARA_CARGAR' ELSE 'DETENIDO_NO_CARGAR' END AS estado;
